export const GLOSSARY_SHARD = Object.freeze({"coin-vs-token":{"slug":"coin-vs-token","cat":"basics","en":"Coin vs token","contentLocale":"zh-Hans","term":"币和代币的区别（Coin vs Token）","aka":["Coin","Token","代币","原生币"],"short":"币（Coin）通常指一条区块链自己的原生资产，如 BTC、ETH；代币（Token）则是基于已有区块链的智能合约发行的资产，如以太坊上的 USDT。","body":[["判断一个资产是币还是代币，关键看它有没有自己的链。",["ETH","ethereum"]," 是以太坊的原生币，用来支付 ",["Gas 费","gas-fee"],"；而以太坊上的 UNI、LINK、",["USDT","usdt"],"（ERC20 版本）都是通过",["智能合约","smart-contract"],"发行的代币，它们共享以太坊的安全性，但转账时仍需用 ETH 付 Gas。"],["同一个代币可以发行在多条链上，比如 USDT 就有以太坊（ERC20）、波场（TRC20）、Solana 等多个版本。它们名字相同，但在不同链上是不同的合约，互相之间不能直接转账，只能通过",["交易所","centralized-exchange"],"或",["跨链桥","cross-chain-bridge"],"转换。"],"日常交流中“币”和“代币”常被混用，交易所也统称为币种。但在充提币时，这个区别非常重要：你要知道这个资产在哪条链上，以及该链需要哪种原生币付手续费。"],"example":"假设你在 Arbitrum 网络上有 200 USDC，想转给朋友，钱包却提示失败。原因是 Arbitrum 上的 Gas 要用 ETH 支付，而你的钱包里 ETH 余额为 0。你需要先转入少量 ETH，比如 0.002 ETH，按 3,000 USDT 一枚计算约 6 USDT，这足够支付很多次 L2 转账的手续费。","mistakes":["以为钱包里有 USDT 就能转账，忘了还要准备链的原生币付 Gas。","把 ERC20 的 USDT 当成 TRC20 的 USDT，往不匹配的网络地址转账。","看到同名代币就当成正品，没核对合约地址，买到了仿冒代币。"],"faq":[{"q":"USDT 是币还是代币？","a":"USDT 是代币。它由 Tether 发行，运行在以太坊、波场、Solana 等多条公链上，本身没有独立的区块链。"},{"q":"BNB 是币还是代币？","a":"BNB 是 BNB Chain 的原生币，用于支付该链的 Gas 费，所以通常被视为币。"}],"title":"币和代币有什么区别？Coin 与 Token 的含义","description":"币（Coin）和代币（Token）的区别是什么？讲清原生币与合约代币、同名代币多链发行，以及为什么转 USDT 还要准备 Gas 费。","related":[["layer-1","一层网络（Layer 1，L1）","一层网络（L1）是指自己负责共识、安全和交易结算的基础区块链，比如比特币、以太坊、Solana 和 BNB Chain。"],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"],["governance-token","治理代币（Governance Token）","治理代币是赋予持有人对协议或 DAO 提案投票权的代币，例如 UNI、AAVE，持有越多投票权越大，但不一定代表能分享协议收入。"],["tokenomics","代币经济学（Tokenomics）","代币经济学是指一个代币的供应量、分配比例、解锁节奏、用途和销毁机制等设计，决定了代币未来的供需结构。"],["altcoin","山寨币（Altcoin）","山寨币是指比特币以外的所有加密货币，包括以太坊、Solana 等公链币，也包括各种应用代币和 Meme 币。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"memecoin":{"slug":"memecoin","cat":"basics","en":"Memecoin","contentLocale":"zh-Hans","term":"Meme 币（Memecoin）","aka":["Memecoin","迷因币","土狗","Meme"],"short":"Meme 币是以网络梗、动物形象或社区文化为主题、通常没有明确实际用途的加密货币，价格主要由社区热度和投机驱动。","body":[["狗狗币（DOGE）是最早出圈的 Meme 币，后来又出现了大量以狗、青蛙、名人梗为主题的代币。很多 Meme 币发行门槛极低，在 Solana、BNB Chain 或",["以太坊","ethereum"],"上几分钟就能发一个，中文圈把这类新发小币叫“土狗”。"],["Meme 币的涨跌主要取决于注意力和情绪，而不是现金流或技术。它们的波动远大于主流币，一天涨跌几十个百分点很常见。新发的 Meme 币还有特别的风险：开发者持有大量份额、",["流动性","liquidity"],"可以被撤走（Rug Pull），或合约里藏有禁止卖出的代码。"],["如果你要接触 Meme 币，先查看持币分布是否集中、",["流动性池","liquidity-pool"],"是否锁定、合约是否被标记风险。大",["交易所","centralized-exchange"],"上线的 Meme 币流动性通常好一些，但价格风险同样很高。"]],"example":["假设你在某 ",["DEX","dex"]," 用 200 ",["USDT","usdt"]," 买了一个刚发行的 Meme 币，池子里只有 5,000 USDT 的流动性。你这笔买入就产生了约 4% 的价格冲击，加上 1% 的交易费。第二天热度退去，价格跌了 60%，你的仓位只剩约 76 USDT；想卖时，池子更浅，卖出又要多损失几个百分点。"],"mistakes":["看到别人晒百倍收益就追高，买在热度最高点。","不查合约就买入，结果是只能买不能卖的“貔貅盘”。","把大额资金放进流动性很浅的土狗，进出都要付出巨大滑点。"],"faq":[{"q":"Meme 币有价值吗？","a":"Meme 币的价值主要来自社区共识和关注度，一般没有现金流或明确用途支撑，所以价格可能长期大幅波动甚至归零。"},{"q":"怎么判断 Meme 币是不是骗局？","a":"可以看前十大持币地址占比、流动性是否锁定、合约是否放弃权限，以及能否正常卖出。这些都只能降低而不能消除风险。"}],"title":"什么是 Meme 币？含义、特点与常见风险","description":"Meme 币（迷因币）是什么？讲清狗狗币和土狗的来历、价格为何由热度驱动，以及 Rug Pull、貔貅盘等新手常见风险。","related":[["altcoin","山寨币（Altcoin）","山寨币是指比特币以外的所有加密货币，包括以太坊、Solana 等公链币，也包括各种应用代币和 Meme 币。"],["rug-pull","跑路（Rug Pull）","Rug Pull（跑路、拉地毯）是指项目方在吸引投资者买入后，突然撤走流动性池中的资金、大量抛售手中代币或卷走资金，导致代币价格瞬间归零。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"]],"lesson":null,"coin":{"slug":"dogecoin","name":"Dogecoin","symbol":"DOGE"},"tool":"/topics/meme-coins","cta":true},"hodl":{"slug":"hodl","cat":"basics","en":"HODL","contentLocale":"zh-Hans","term":"HODL（长期持有）","aka":["囤币","拿住","Hold"],"short":"HODL 是币圈对“长期持有不卖出”的俗称，源自 2013 年论坛里把 hold 拼错的帖子，后来也被解释为 Hold On for Dear Life。","body":[["HODL 指的是不管短期涨跌都继续持有，而不是频繁买卖。它源于一位用户在",["比特币","bitcoin"],"大跌时发的拼写错误帖子，后来成为币圈文化的一部分。中文圈常说“囤币”“拿住”“死拿”。"],["长期持有的好处是减少交易次数、手续费和情绪化操作；但它不等于什么币都可以闭眼拿着。很多",["山寨币","altcoin"],"长期看是持续下跌甚至归零的，HODL 更适合你充分了解、并能承受大幅回撤的资产。"],["长期持有时，保管方式很重要。放在",["交易所","centralized-exchange"],"方便交易，但要承担平台风险；转到自己的",["冷钱包","cold-wallet"],"更安全可控，但要妥善备份",["助记词","seed-phrase"],"。可以结合",["定投","dollar-cost-averaging"],"来分散买入时点。"]],"example":"假设你在 BTC 价格 40,000 USDT 时买入 0.05 BTC，花了 2,000 USDT。之后一年里价格先跌到 25,000，再涨到 70,000。如果你一直持有，最终价值 3,500 USDT，赚 1,500 USDT；但在最低点时，你的仓位一度只剩 1,250 USDT，浮亏 37.5%。能不能熬过那段回撤，才是 HODL 真正的难点。","mistakes":["把 HODL 当成对任何山寨币都适用的策略，结果拿到归零。","长期持有却放在不了解的小平台，平台出问题时资产无法取出。","冷钱包助记词只存一份，丢失后资产永久无法找回。"],"faq":[{"q":"HODL 是什么意思？","a":"HODL 是 hold 的误拼，在币圈指长期持有、不因短期波动卖出。也常被解读为 Hold On for Dear Life。"},{"q":"HODL 和定投有什么关系？","a":"定投是分批买入的方法，HODL 是买入后的持有态度。很多长期持有者会用定投来积累仓位。"}],"title":"HODL 是什么意思？币圈长期持有的含义","description":"HODL 在币圈是什么意思？讲清这个词的来历、长期持有的优点与局限，以及囤币时如何选择交易所托管或冷钱包保管。","related":[["dollar-cost-averaging","定投（DCA）","定投（DCA）是按固定周期、用固定金额买入同一资产的策略，不去猜测高低点，借助分批买入摊平成本、降低一次性买在高位的风险。"],["cold-wallet","冷钱包（冷存储）","冷钱包是把私钥保存在不联网环境中的钱包或存储方式，例如硬件钱包和离线生成的纸钱包，主要用于长期、安全地存放大额加密资产。"],["bear-market","熊市（Bear Market）","熊市是指加密货币或其他资产价格在较长时间内持续下跌、市场情绪悲观、成交量和关注度明显下降的阶段，与之相对的是牛市。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"liquidity-pool":{"slug":"liquidity-pool","cat":"defi","en":"Liquidity pool","contentLocale":"zh-Hans","term":"流动性池（Liquidity Pool）","aka":["流动性池","资金池","LP 池","Liquidity pool"],"short":"流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。","body":[["你向流动性池按当前价格比例存入两种代币，例如 ",["ETH","ethereum"]," 和 ",["USDC","usdc"],"，就会收到一个代表份额的 LP 凭证。每笔交易支付的手续费会留在池子里，取出时你按份额拿回两种代币加上累积的手续费。"],["流动性池让 ",["DEX","dex"]," 不再依赖专业",["做市商","market-maker"],"，任何人都能为新代币创建",["交易对","trading-pair"],"。但这也带来风险：池子太浅时",["滑点","slippage"],"大；代币价格剧烈变化会造成无常损失；如果是项目方自己建的池子，还可能被撤池子（Rug Pull）。"],"评估一个池子时可以看总流动性、交易量与手续费比例、代币本身的风险，以及流动性是否锁仓。"],"example":"假设一个 ETH/USDC 池子共有 200 ETH 和 600,000 USDC，你存入 2 ETH 和 6,000 USDC，占池子的 1%。如果一个月内该池产生 30,000 USDC 的手续费，你按份额可获得约 300 USDC。但如果这期间 ETH 价格大幅变化，你取回的 ETH 和 USDC 数量会与存入时不同，需要和单纯持有的结果比较。","mistakes":["只看页面上的年化收益，不考虑无常损失和代币本身的下跌。","往刚创建、流动性未锁仓的新币池子里加流动性。","弄丢或误转了 LP 凭证，导致无法取回池中份额。"],"faq":[{"q":"流动性池的收益来自哪里？","a":"主要来自交易手续费，部分项目还会额外发放代币奖励。奖励代币的价格波动大，实际收益要按到手价值计算。"},{"q":"存进流动性池会亏钱吗？","a":"会。币价变化导致的无常损失、奖励代币下跌、合约被攻击或项目跑路，都可能让最终结果低于单纯持有。"}],"title":"什么是流动性池？LP 收益来源与风险","description":"流动性池是什么意思？了解 DEX 流动性池如何运作、LP 凭证代表什么、手续费收益怎么计算，以及提供流动性前要评估的风险。","related":[["amm","自动做市商（AMM）","自动做市商（AMM）是一种用流动性池和数学公式自动给代币定价的交易机制，不需要买卖双方挂单撮合，是 Uniswap 等去中心化交易所的核心。"],["impermanent-loss","无常损失（Impermanent Loss）","无常损失是指你在 AMM 流动性池中提供流动性时，因两种代币价格比例变化，导致取回资产的价值低于单纯持有这些代币所造成的差额。"],["yield-farming","流动性挖矿（Yield Farming）","流动性挖矿是指把加密资产存入 DeFi 协议提供流动性或借贷，以赚取手续费、利息以及协议额外发放的代币奖励的做法。"],["rug-pull","跑路（Rug Pull）","Rug Pull（跑路、拉地毯）是指项目方在吸引投资者买入后，突然撤走流动性池中的资金、大量抛售手中代币或卷走资金，导致代币价格瞬间归零。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"perp-dex":{"slug":"perp-dex","cat":"defi","en":"Perp DEX (on-chain perpetuals)","contentLocale":"zh-Hans","term":"永续合约 DEX（Perp DEX）","aka":["Perp DEX","链上永续合约","去中心化合约交易所","去中心化永续"],"short":"永续合约 DEX（Perp DEX）是在链上提供永续合约交易的去中心化平台，你用自己的钱包存入保证金开多或开空，资金费率、强平等机制与中心化交易所类似。","body":[["Perp ",["DEX","dex"]," 有多种设计：Hyperliquid 运行在自己的链上并采用链上",["订单簿","order-book"],"；dYdX 也使用订单簿模式；还有一些平台采用",["流动性池","liquidity-pool"],"作为",["交易对","trading-pair"],"手，由 LP 承担交易者的盈亏。"],["与",["中心化交易所","centralized-exchange"],"相比，你不需要注册账户，资金在合约或链上账户中而不是交易所托管；交易和清算记录公开可查。但你依然面对",["杠杆交易","margin-trading"],"的全部风险：资金费率、强平（爆仓）、滑点，另外还有合约漏洞、预言机异常和跨链充值的风险。"],"不同 Perp DEX 的杠杆上限、资金费率结算频率、支持的保证金币种和费用都不同，部分平台按小时结算资金费率。交易前查看平台的合约说明页面。"],"example":"假设你在 Perp DEX 存入 1,000 USDC，以 5 倍杠杆在 BTC 价格 60,000 USDC 时开多，仓位价值 5,000 USDC，约 0.0833 BTC。BTC 跌 10% 到 54,000 USDC 时，亏损约 500 USDC，保证金剩约 500 USDC。若继续下跌接近 20% 并触及维持保证金要求，仓位会被强平，剩余保证金大部分损失。","mistakes":["以为链上交易就没有爆仓风险，开了过高杠杆。","忽略资金费率按小时结算，长期持仓成本比预期高。","通过不明跨链桥充值保证金，资金在途中出问题。"],"faq":[{"q":"Perp DEX 和中心化交易所合约有什么区别？","a":"Perp DEX 由智能合约或专用链执行，资产不交给公司托管，记录透明；中心化交易所功能和流动性通常更全面，但资产由平台托管。"},{"q":"Perp DEX 需要 KYC 吗？","a":"很多 Perp DEX 只需连接钱包即可交易，但部分前端会限制某些地区访问，具体以平台规则和所在地法规为准。"}],"title":"什么是 Perp DEX？链上永续合约交易所","description":"Perp DEX 是什么？了解链上永续合约交易所的订单簿与资金池模式、与中心化交易所合约的区别，以及杠杆、资金费率和强平风险。","related":[["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["non-custodial-wallet","非托管钱包（自托管钱包）","非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。"]],"lesson":null,"coin":{"slug":"hyperliquid","name":"Hyperliquid","symbol":"HYPE"},"tool":"/funding-rates","cta":false},"copy-trading":{"slug":"copy-trading","cat":"exchange-features","en":"Copy trading","contentLocale":"zh-Hans","term":"跟单交易（Copy trading）","aka":["跟单","带单","Copy trading","复制交易"],"short":"跟单交易是交易所提供的一种功能，让你选择一位公开交易记录的带单员，按设定的比例或金额自动复制他的开仓和平仓操作。","body":[["OKX、Bybit、Bitget等",["交易所","centralized-exchange"],"都提供跟单功能，常见的有合约跟单和现货跟单。带单员的历史收益率、最大回撤、胜率和跟随人数会公开展示；你设置跟单金额、每笔跟单比例或固定金额，以及是否同步",["杠杆倍数","leverage"],"。"],"带单员盈利时，通常会从跟单者的盈利中抽取一定比例的分润，具体比例由平台和带单员设定。跟单者亏损时不需要付分润，但亏损全部由自己承担。","跟单的核心风险在于你看不到带单员的真实风控。高收益率可能来自高杠杆和少数幸运交易，一次极端行情就可能爆仓。由于成交时点和价格可能与带单员不同，你的结果也可能与他展示的收益有偏差。给每个带单员设定资金上限、止损，并分散跟随，比全部押在一个人身上更稳妥。"],"example":["假设你用1,000 USDT跟随一位合约带单员，他用10倍杠杆做多BTC，你的跟单设置使用全部1,000 USDT作为保证金，名义仓位10,000 ",["USDT","usdt"],"。BTC下跌8%，仓位亏损800 USDT，账户只剩200 USDT。如果你事先设置了20%的跟单止损，亏损达到200 USDT时就会自动停止跟随并平仓，还能保住约800 USDT。若这笔交易盈利300 USDT，按10%的分润比例，你需要支付30 USDT。"],"mistakes":["只看30天收益率排行就跟随，不看最大回撤和使用的杠杆倍数。","把大部分资金跟随同一个带单员，没有设置跟单止损。","以为跟单结果会和带单员展示的收益完全一样，忽略滑点和成交时间差。"],"faq":[{"q":"跟单会亏钱吗？","a":"会。跟单只是复制他人的交易，带单员亏损时你也同样亏损，合约跟单使用杠杆时还可能爆仓。"},{"q":"怎么挑选跟单的带单员？","a":"看较长周期的收益和最大回撤、杠杆习惯、交易频率和跟单者实际收益，而不是只看短期收益率排名。"}],"title":"什么是跟单交易？带单员分润与跟单风险","description":"跟单交易是什么？了解合约跟单和现货跟单如何运作、带单员分润怎么算、为什么高收益可能隐藏高杠杆，以及如何设置跟单止损。","related":[["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["risk-reward-ratio","盈亏比（Risk-Reward Ratio）","盈亏比是一笔交易计划中可能亏损的金额与可能盈利的金额之比，例如止损亏 100、止盈赚 300，就是 1:3 的盈亏比。"],["grid-trading-bot","网格交易机器人（Grid trading bot）","网格交易机器人是在你设定的价格区间内按等距价位自动挂出一组买单和卖单的交易工具，价格每下跌一格就买入、每上涨一格就卖出，赚取震荡中的差价。"]],"lesson":null,"coin":null,"tool":"/compare","cta":true}});
